      "project_code": "FP43",
      "title": "Bridging the Scale Gap: A Drone–Satellite Foundation Model for Unified Earth Representation Learning",
      "description": "\nDevelop a unified foundation model that aligns drone and satellite imagery within a shared representation space, enabling knowledge transfer across spatial scales for precise and scalable Earth monitoring.\n",
